CREATE TABLE IF NOT EXISTS saliyah_sim_border_events (id TEXT PRIMARY KEY,citizen_id TEXT NOT NULL REFERENCES saliyah_sim_citizens(id),port TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN ('entry','exit')),inspection_status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS saliyah_sim_incidents (id TEXT PRIMARY KEY,suspect_id TEXT NOT NULL REFERENCES saliyah_sim_citizens(id),officer TEXT NOT NULL,allegation TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'reported',arrested_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS saliyah_sim_trials (id TEXT PRIMARY KEY,incident_id TEXT NOT NULL REFERENCES saliyah_sim_incidents(id),judge TEXT NOT NULL,verdict TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'scheduled',completed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)